    for (const x of ins) { if (!/^\d+$/.test(x)) return { ok: false, why: '根號裡還有分數或算式' }; const [o] = sqfree(BigInt(x)); if (o > 1n || x === '1' || x === '0') return { ok: false, why: `√${x} 還能化簡` }; }
