  // ---------- 判讀：一個乘積式錯在哪 ----------
  // 回傳 diag 代碼：standard / has1 / wrongValue / composite / notCombined / order / unparsable
  function diagnoseFactorization(text, n) {
    const f = parseProduct(text);
    if (!f) return { diag: 'unparsable', msg: '不是乘積式' };
    const val = productValue(f);
    if (f.some(([b]) => b === 1)) return { diag: 'has1', msg: '含有因數 1' };
    if (val !== n) return { diag: 'wrongValue', msg: `乘開是 ${val}，不是 ${n}` };
    if (f.some(([b]) => !isPrime(b))) return { diag: 'composite', msg: '還有合數沒分解完' };
    const bases = f.map(([b]) => b);
    if (new Set(bases).size !== bases.length) return { diag: 'notCombined', msg: '相同質因數沒有合併成次方' };
    for (let k = 1; k < bases.length; k++) if (bases[k] < bases[k - 1]) return { diag: 'order', msg: '質因數沒有由小到大排列' };
    return { diag: 'standard', msg: '標準分解式' };
  }

