  // 子句比對前的統一寫法：去空白，= + - , （ ） → ＝ ＋ − ， ( )
  const pbNz = t => String(t).replace(/\s+/g, '').replace(/=/g, '＝').replace(/\+/g, '＋').replace(/-/g, '−').replace(/,/g, '，').replace(/（/g, '(').replace(/）/g, ')');
