    if (view === 'right') return viewSky([...Array(R).keys()].reverse().map(rowMax));   // 站在右邊：左手邊是前面（最前排畫在最左）
    if (view === 'left') return viewSky([...Array(R).keys()].map(rowMax));               // 站在左邊：左手邊是後面
    if (view === 'top') return M.map(r => r.map(v => v > 0 ? '1' : '0').join('')).join('/');   // 上緣是最後一排、下緣是最前排
