    const rho = pbQ(evalQ(p[0])), X = netLen(p[1]), Y = netLen(p[2]), c = Number(p[3]), r = qDiv(pbQ(evalQ(String(d))), Q(2n)), H = pbQ(evalQ(String(h)));
    if (!(c === 1 || c === 2)) throw new Error('圓的個數要是 1 或 2：' + code);
    const why = [];
    if (!qEq(rho, r)) why.push(`圓的半徑 ${fmtQ(rho)} 不是 ${fmtQ(r)}`);
    if (!(X.pi && qEq(X.q, qMul(Q(2n), rho)))) why.push('接圓的那一邊不等於圓周長');
    if (Y.pi || !qEq(Y.q, H)) why.push(`另一邊不是高 ${fmtQ(H)}`);
