          ok = Math.min(a, b, c) / Math.max(a, b, c) > 0.25 && !eqR(a, b) && !eqR(b, c) && !eqR(a, c) && ms.every(m => m > 18 * D2R && Math.abs(m - Math.PI / 2) > 4 * D2R);
