          let a = a0; const ps = gaps.map(gp => { const q = [(1 + 0.8 * r()) * Math.cos(a), (1 + 0.8 * r()) * Math.sin(a)]; a += gp / tot * 2 * Math.PI; return q; });
          let ok = true; for (let j = 0; j < 4; j++) { const p0 = ps[(j + 3) % 4], p1 = ps[j], p2 = ps[(j + 1) % 4]; if (crs(sub(p1, p0), sub(p2, p1)) <= 0) ok = false; const m = angAt(p0, p1, p2); if (m < 40 * D2R || m > 150 * D2R) ok = false; }   // 凸、內角 40°～150°
