      const need = (...ss) => { ss.forEach(s => { if (s === 'L') { if (!names.includes('L')) throw new Error('沒有直線 L'); return; } if (s.length === 1 ? !has(s) : !segOK(s)) throw new Error('沒有這個點或線段：' + s); }); };
