    GC03a: { mis: 'GC03', name: '以為沒有最大公因數', excl: 'GC03', fn: ({ a, b }) => gcd2(a, b) !== 1 ? null : ({ text: '沒有最大公因數', trace: `${a} 與 ${b} 沒有共同的質因數，就以為沒有最大公因數`, fix: `1 是任何兩數的公因數，${a} 與 ${b} 的最大公因數是 1` }) },
    GC03b: { mis: 'GC03', name: '以為最大公因數是 0', excl: 'GC03', fn: ({ a, b }) => gcd2(a, b) !== 1 ? null : ({ value: 0, trace: `${a} 與 ${b} 沒有共同的質因數，就把最大公因數寫成 0`, fix: `0 不是 ${a} 的因數，${a} 與 ${b} 的最大公因數是 1` }) },
