    GC01e: { mis: 'GC01', name: '不是質數就以為不互質', fn: ({ a, b }) => (gcd2(a, b) !== 1 || V.isPrime(a) || V.isPrime(b)) ? null : ({ text: '大於 1（兩數都不是質數）', trace: `看到 ${a} 與 ${b} 都不是質數，就以為兩數不互質`, fix: `${a} 與 ${b} 沒有共同的質因數，最大公因數是 1，兩數互質` }) },
    GC04a: { mis: 'GC04', name: '短除法只除一次就停', fn: ({ a, b }) => { const g = gcd2(a, b); if (g === 1) return null; const p = smallestFactor(g); if (p === g) return null; return { value: p, trace: `短除法只除一次 ${p} 就停，下面的 ${a / p}、${b / p} 還有公因數 ${g / p}，就把 ${p} 當成最大公因數`, fix: `${p} 是公因數但不是最大的，要除到兩數互質，最大公因數是 ${g}` }; } },
    GC04b: { mis: 'GC04', name: '短除法只除一次就停', fn: ({ a, b }) => { const g = gcd2(a, b); if (g === 1) return null; const fs = V.factorize(g), p = fs[fs.length - 1][0]; if (fs.length < 2) return null; return { value: p, trace: `短除法只除一次 ${p} 就停，下面的 ${a / p}、${b / p} 還有公因數 ${g / p}，就把 ${p} 當成最大公因數`, fix: `${p} 是公因數但不是最大的，要除到兩數互質，最大公因數是 ${g}` }; } },
    GC05n: { mis: 'GC05', name: '共同質因數次方取大的', fn: ({ a, b }) => { const g = gcd2(a, b); if (g === 1) return null; const fa = new Map(V.factorize(a)), fb = new Map(V.factorize(b)); let v = 1; fa.forEach((e, p) => { if (fb.has(p)) v *= pow(p, Math.max(e, fb.get(p))); }); if (v === g || v === lcm2(a, b)) return null; return { value: v, trace: `共同的質因數取了次方較大的，得 ${sup(fT(v))}＝${v}`, fix: `最大公因數要取次方較小的：${sup(fT(g))}＝${g}` }; } },
