  const PREC = { '+': 1, '-': 1, '*': 2, '÷': 2, neg: 2.5, '/': 3, '^': 4 };
  const SYM = { '+': '＋', '-': '−', '*': '×', '÷': '÷', '/': '/', '^': '^' };
