      if (n.t === 'neg' && n.a.t === 'paren' && unP(n.a).t === 'bin' && ['+', '-'].includes(unP(n.a).op)) { const g = unP(n.a); return { t: 'bin', op: g.op, a: { t: 'neg', a: g.a }, b: g.b }; }
