    dropParens: { name: '忽略括號，照寫的順序算', ex: '2×(3＋4) → 2×3＋4', whole: true },
    absAsParen: { name: '把絕對值當成括號', ex: '5−|−8| → 5−(−8)', f: n => n.t === 'abs' ? { t: 'paren', a: n.a } : n },
    numOnly: { name: '分數的次方只算分子', ex: '(2/3)^4 → 2^4/3', f: n => n.t === 'bin' && n.op === '^' && isFrac(n.a) ? { t: 'bin', op: '/', a: { t: 'bin', op: '^', a: unP(n.a).a, b: n.b }, b: unP(n.a).b } : n },
    denOnly: { name: '分數的次方只算分母', ex: '(2/3)^4 → 2/3^4', f: n => n.t === 'bin' && n.op === '^' && isFrac(n.a) ? { t: 'bin', op: '/', a: unP(n.a).a, b: { t: 'bin', op: '^', a: unP(n.a).b, b: n.b } } : n },
    rightToLeft: { name: '由右往左算（先算後面）', ex: '10−3＋2 → 10−(3＋2)', f: n => rtl(n) },
    ignoreNeg: { name: '忽略負號，只算數字', ex: '(−4)×3 → 4×3', f: n => n.t === 'neg' ? n.a : (n.t === 'paren' && n.a.t === 'num') ? n.a : n },
    expMul: { name: '同底數相乘，指數相乘', ex: '2^3×2^4 → 2^12', f: n => {
      if (n.t !== 'bin' || n.op !== '*') return n; const A = unP(n.a), B = unP(n.b);
      if (A.t !== 'bin' || A.op !== '^' || B.t !== 'bin' || B.op !== '^' || myPrint(A.a) !== myPrint(B.a)) return n;
      const e = QOP['*'](myEval(A.b), myEval(B.b)); return { t: 'bin', op: '^', a: A.a, b: { t: 'num', q: e, s: qStr(e) } }; } },
    fracAddEach: { name: '分數相加：分子加分子、分母加分母', ex: '1/2＋1/3 → 2/5', f: n => n.t === 'bin' && ['+', '-'].includes(n.op) && isFrac(n.a) && isFrac(n.b) ? { t: 'bin', op: '/', a: { t: 'paren', a: { t: 'bin', op: n.op, a: unP(n.a).a, b: unP(n.b).a } }, b: { t: 'paren', a: { t: 'bin', op: n.op, a: unP(n.a).b, b: unP(n.b).b } } } : n }
