    if (!String(spec.expr || '').trim() || !/\d/.test(spec.expr)) return { ok: false, msg: NOALGO };
    if (!Array.isArray(ids) || !ids.length || ids.length > 3) return { ok: false, msg: '變形要 1～3 個' };
    const bad = ids.filter(x => !TRANSFORMS[x]); if (bad.length) return { ok: false, msg: '不在白名單的變形：' + bad.join('、') };
    let tree, right, got, steps, want;
    try { tree = myParse(spec.expr); right = myEval(tree); } catch (e) { return { ok: false, msg: '例子的算式：' + e.message }; }
