  // ---------- 題型：正解、選項比對鍵 ----------
  // key：撞值檢查用的比對鍵（值相同的選項視為相同）
  const numKey = t => { try { return V.fmtQ(V.evalQ(String(t))); } catch (e) { return 'T:' + t; } };
  // 因式分解選項：兩個一次因式相乘時，因式前後對調算同一個（(x−3)(x−5)＝(x−5)(x−3)）
  const facKey = t => { const s = String(t).replace(/\s+/g, ''), m = /^\((\d*)x([＋−]\d+)\)\((\d*)x([＋−]\d+)\)$/.exec(s);
    return m ? 'F:' + [m[1] + 'x' + m[2], m[3] + 'x' + m[4]].sort().join('|') : 'T:' + s; };
  // 七上2-2：「a 與 b」前後對調算同一組；數值去掉單位後比值（2^3×3 和 24 算相同）；「沒有最大公因數」這類文字維持文字比對
  const pairKey = t => 'P:' + String(t).split(/與|和/).map(x => x.trim()).sort((x, y) => x - y).join('|');
  const gcKey = t => { const s = String(t).replace(/\s+/g, ''), m = /^[\d^×]+/.exec(s); return m && (m[0].length === s.length || !/[×^]/.test(s.slice(m[0].length))) ? numKey(m[0]) : 'T:' + s; };
  const KINDS = {
    factorize: { key: t => 'T:' + String(t).replace(/\s+/g, '') },
    pfValue: { key: numKey }, pfCount: { key: numKey },
    pfSet: { key: t => 'S:' + String(t).split('、').map(Number).sort((x, y) => x - y).join(',') },
    pfIsFactor: { key: numKey }, pfIsPrime: { key: numKey },
    asAdd: { key: numKey }, asSub: { key: numKey }, asParen: { key: numKey }, asAbs: { key: numKey }, asDist: { key: numKey }, asRange: { key: numKey },
    exPow: { key: numKey }, exSubPow: { key: numKey }, ex01: { key: numKey }, exNeg10: { key: numKey }, exCmp: { key: numKey },
    exSci: { key: t => 'T:' + String(t).replace(/\s+/g, '') },                          // 值相同、寫法不同（235×10^4）也算不同選項
    elMul: { key: numKey }, elDiv: { key: numKey }, elPowPow: { key: numKey }, elProd: { key: numKey }, elFrac: { key: numKey }, elZero: { key: numKey },
    cxPos: { key: facKey }, cxNeg: { key: facKey }, cxA: { key: facKey }, cxK: { key: numKey },
    gcCoprime: { key: pairKey }, gcGcd: { key: gcKey }, gcPfG: { key: gcKey }, gcPfL: { key: gcKey }, gcLcm: { key: gcKey }, gcGrpN: { key: gcKey }, gcGrpPer: { key: gcKey }, gcMeet: { key: gcKey }
  };
  function registerKind(name, def, rules) { KINDS[name] = def; R[name] = rules; }   // 其他單元的規則檔用這個加題型
  // v3.10：各單元的規則檔（src/units/<單元>.js，build 時接在本檔後面）用 registerFn 加模板算式能用的函式
  function registerFn(name, fn) { if (Object.prototype.hasOwnProperty.call(FNS, name)) throw new Error('函式名稱重複：' + name); FNS[name] = fn; }
  // 比對鍵（v3.10）：text＝寫法完全相同才算同一個；unitNum＝「5 個」「5 組」去掉單位比值；frac＝值相同且「最簡／沒約分」相同算同一個
  // （14/30 和 7/15 算不同：一個是沒約分的誘答；1又1/3 和 4/3 算相同：都是正解）；expr＝代數式在幾個取樣點的值都相同算同一個
  const textKey = t => 'T:' + String(t).replace(/\s+/g, '');
  const unitNumKey = t => { const s = String(t).trim(), m = /^(.*?[\d)])\s*(?:[一-鿿]+|°)$/.exec(s); return numKey(m ? m[1] : s); };
  const fracKey = t => { const s = String(t).replace(/\s+/g, ''), L = V.parseFracLit(s); return L ? 'Q:' + V.fmtQ(L.q) + (L.reduced ? '' : '~') : numKey(s); };
  // v3.15：式子裡沒有 x、有 n 時改代 n（等差數列一般項 23−3n＝−3n＋23）；有 x 的照舊只代 x
  const exprKey = t => { const s = String(t), v = !/x/.test(s) && /n/.test(s) ? 'n' : 'x'; try { return 'E:' + ['7/3', '-5/2', '11'].map(x => { const r = V.evalV(s, { [v]: V.evalQ(x) }); return r.u ? 'U' : V.fmtQ(r); }).join(','); } catch (e) { return textKey(t); } };
  // rad（v3.13）：值相同而且都是最簡根式才算同一個；沒化簡的照原寫法比（2√18 和 6√2 不同、8＋4√3 和 4√3＋8 相同）；±、文字選項照文字比
  const radKey = t => { const s = String(t).replace(/\s+/g, ''); if (/±/.test(s)) return textKey(s); try { const v = V.evalR(s); return 'R:' + V.fmtR(v) + (V.radFormOK(s).ok ? '' : '~' + s); } catch (e) { return textKey(s); } };
  // set（v3.14）：數的集合「5 或 √7」＝「√7 或 5」、「只有 5」＝「5」；看不懂照文字比
  const setKey = t => { try { return 'S:' + [...new Set(V.parseRootSet(String(t).replace(/^\s*只有\s*/, '')).map(V.fmtR))].sort().join('|'); } catch (e) { return textKey(t); } };
  // pi（v3.14）：含 π 的選項比係數（2π、π、10/3π）；沒有 π 的照數值比
  const piKey = t => { const s = String(t).replace(/\s+/g, ''); if (/π/.test(s)) { const c = s.replace(/([\d)])π/, '$1').replace('π', '1'); try { return 'PI:' + V.fmtQ(V.evalQ(c)); } catch (e) { return textKey(s); } } return numKey(s); };
  // pt（v3.15）：有序數對 (a, b) 兩個坐標依值比對（(6/2, 0)＝(3, 0)、全形括號逗號也可）；看不懂照文字比
  const ptKey = t => { const m = /^[（(]\s*([^,，]+)[,，]\s*([^)）]+)[)）]$/.exec(String(t).trim()); if (!m) return textKey(t); try { return 'P:' + V.fmtQ(V.evalQ(m[1])) + ',' + V.fmtQ(V.evalQ(m[2])); } catch (e) { return textKey(t); } };
