  const ordKey = t => { const s = String(t).replace(/\s+/g, ''), m = /^第([−-]?\d+)(?:項|個圖|個|圖)?$/.exec(s); return m ? 'N:' + V.fmtQ(V.evalQ(m[1])) : numKey(s); };
  // piRad（v3.20，第 13 批）：「aπ＋b」（a、b 可含根式）依 π 的係數與其餘部分比對（6π−9√3＝−9√3＋6π；4π＋20 和 π＋23 不同，pi 鍵會把兩個都當成 24）；看不懂（「沒有這樣的弦」）照文字比
  const piRadKey = t => { try { const v = V.piVal(t); return 'PR:' + V.fmtR(v.coef) + '|' + V.fmtR(v.rest); } catch (e) { return textKey(t); } };
  const KEYS = { num: numKey, text: textKey, unitNum: unitNumKey, frac: fracKey, expr: exprKey, rad: radKey, set: setKey, pi: piKey, pt: ptKey, ineq: ineqKey, ord: ordKey, piRad: piRadKey };

  // ---------- 亂數（可給種子，測試結果固定） ----------
  function rng(seed) {
    let s = (seed >>> 0) || (Math.floor(Math.random() * 2 ** 32) >>> 0);
    return () => { s = (s + 0x6D2B79F5) >>> 0; let t = s; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  }
  const pickOne = (arr, r) => arr[Math.floor(r() * arr.length)];
  function shuffle(a, r) { a = a.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }

  // ---------- 回饋文字整理（v3.12）：學生看到的 trace／fix／正解回饋一律用全形負號，係數 1 不寫（1x→x、−1x→−x），＋− 這類連號合併 ----------
  const tidy = t => t == null ? t : String(t)
    .replace(/＋\s*[−-]/g, '−').replace(/[−-]\s*[−-]/g, '＋')
    .replace(/(^|[^\w)）\]])-(?=[\d(（x])/g, '$1−')
    .replace(/(^|[^\d.\/\w])1(x)/g, '$1$2');
  // ---------- 單一規則執行 ----------
  function runRule(kind, id, P) {
    const rule = R[kind] && R[kind][id]; if (!rule) throw new Error(`題型 ${kind} 沒有規則 ${id}`);
    const o = rule.fn(P); if (!o) return null;
    const text = o.text !== undefined ? String(o.text) : (o.value !== undefined ? sgn(o.value) : null);
    return { rule: id, mis: rule.mis, text, value: o.value, trace: tidy(o.trace), fix: tidy(o.fix) };
  }

  // 抽一組參數（符合 when），算出 let
  function sampleParams(tpl, r, fixed) {
    const P = {};
    for (const [k, v] of Object.entries(tpl.params || {})) P[k] = fixed && k in fixed ? fixed[k] : Array.isArray(v) ? pickOne(v, r) : v;
    for (const [k, e] of Object.entries(tpl.let || {})) P[k] = evalT(e, P);
    if (tpl.when && !evalT(tpl.when, P)) return null;
    return P;
  }
  function sampleValid(tpl, r, fixed) {                                   // 抽到符合 when 為止（when 不算在 50 次重抽裡）
    for (let i = 0; i < 5000; i++) { const P = sampleParams(tpl, r, fixed); if (P) return P; }
    return null;
  }

  // 一組參數 → 正解＋所有可用規則的誘答（還沒挑）
  const myOk = tpl => tpl.check && tpl.check.type === 'value' && tpl.check.expr;      // 我的迷思只用在「算式→數值」的模板
  function runAny(tpl, id, P, custom) {
    if (!id.startsWith('MY:')) return runRule(tpl.kind, id, P);
    const sp = (custom || []).find(c => 'MY:' + c.code === id); if (!sp || !myOk(tpl)) return null;
    const o = myRuleOn(sp, fill(tpl.check.expr, P)); return o && { rule: id, mis: sp.code, text: o.text, trace: o.trace, fix: o.fix };
  }
  function evaluate(tpl, P, ruleIds, custom) {
    const kind = KINDS[tpl.kind]; if (!kind) throw new Error('沒有這種題型：' + tpl.kind);
    const av = evalT(tpl.answer, P), ansText = typeof av === 'number' ? sgn(av) : String(av);
    const out = { P, ansText, ansKey: kind.key(ansText), cands: [] };
    ruleIds.forEach(id => { const d = runAny(tpl, id, P, custom); if (d) out.cands.push(d); });
    return out;
  }

  // 互斥（v3.7.1）：規則寫 excl:'組名'，同一題同一組只出一條（例：七上2-2 的「沒有最大公因數」與「0」）
  const exclOf = (kindName, id) => { const r = R[kindName] && R[kindName][id]; return r && r.excl || null; };
  const effCount = (kindName, ids) => new Set(ids.map(id => exclOf(kindName, id) || id)).size;   // 互斥組只算一條

  // 依序挑 pick 條：不等於正解、彼此不同；規則要在 A、B 兩組數字都能用
  function choose(evA, evB, tpl, ruleIds, need, kind) {
    const chosen = [], usedA = new Set([evA.ansKey]), usedB = new Set([evB.ansKey]), usedEx = new Set();
    for (const id of ruleIds) {
      if (chosen.length >= need) break;
      const ex = exclOf(tpl.kind, id); if (ex && usedEx.has(ex)) continue;
      const a = evA.cands.find(d => d.rule === id), b = evB.cands.find(d => d.rule === id);
      if (!a || !b) continue;
      const ka = kind.key(a.text), kb = kind.key(b.text);
      if (usedA.has(ka) || usedB.has(kb)) continue;
      usedA.add(ka); usedB.add(kb); chosen.push(id); if (ex) usedEx.add(ex);
    }
    return chosen.length === need ? chosen : null;
  }

  function buildItem(tpl, ev, chosen, set, pair, ansPos, r) {
    const opts = [{ text: ev.ansText, mis: null, feedback: tidy(fill(tpl.okfb || '正確！', ev.P)) }];
    chosen.forEach(id => { const d = ev.cands.find(x => x.rule === id); opts.push({ text: d.text, mis: d.mis, rule: id, trace: d.trace, fix: d.fix, feedback: `${d.trace}。${d.fix}。` }); });
    // 正解放在 ansPos，其他亂排
    const wrong = shuffle(opts.slice(1), r); const arr = []; let w = 0;
    for (let i = 0; i < opts.length; i++) arr.push(i === ansPos ? opts[0] : wrong[w++]);
    const keyed = arr.map((o, i) => Object.assign({ key: 'ABCD'[i] }, o));
    const item = {
      id: pair + set, set, pair, bloom: tpl.bloom || '理解', lc: tpl.lc || '', stem: fill(tpl.stem, ev.P),
      options: keyed, answer: 'ABCD'[ansPos], check: fillDeep(tpl.check, ev.P), hint: tpl.hint ? fill(tpl.hint, ev.P) : '',
      tpl: tpl.tpl, params: ev.P, gen: 'template',
      ...(tpl.seg ? { seg: tpl.seg } : {}), ...(tpl.fig ? { fig: tpl.optLabels ? '' : makeFig(tpl.fig, ev.P) } : {}), ...(tpl.optional ? { optional: true } : {})   // v3.9：主幹卡段落、動態附圖；v3.15：模板 optional（進階）帶到題目，老師選題預設不勾
    };
    return tpl.optLabels ? optRelabel(item, tpl) : item;   // 第 12 批：選項是圖
  }

  // 第 12 批：選項是圖（模板寫 optLabels:'甲乙丙丁'）。規則照常回傳「圖的代碼」當選項文字（撞值、互斥照舊比代碼）；排好 A～D 之後：
  //   1. 原代碼留在 o.code，選項文字依位置換成甲、乙、丙、丁；2. check 補 cands:{甲:代碼,…}（驗算器用它查每個選項的圖）；
  //   3. 附圖參數多 OPTS（A～D 順序的代碼陣列，fig 寫 opts:'{OPTS}'）重畫。換誘答（replaceDistractor）後也呼叫這個重畫。題目的 params 不放 OPTS
  function optRelabel(it, tpl) {
    const labs = [...String(tpl.optLabels)]; if (labs.length < it.options.length) throw new Error(`模板 ${tpl.tpl} 的 optLabels 只有 ${labs.length} 個字`);
    const codes = it.options.map(o => o.code !== undefined ? o.code : o.text);
    it.options.forEach((o, i) => { o.text = labs[i]; o.code = codes[i]; });
    it.check = Object.assign({}, it.check, { cands: Object.fromEntries(codes.map((c, i) => [labs[i], c])) });
    if (tpl.fig) it.fig = makeFig(tpl.fig, Object.assign({}, it.params, { OPTS: codes }));
    return it;
  }

  // ---------- 出題器：一個模板 → 一組平行題（A、B 卷） ----------
  // opt：{ pair:'P01', seed, rules:[可用的規則 id]（老師勾的迷思篩過）, misMap（用來驗算迷思代碼）, maxTry:50 }
  function genPair(tpl, opt = {}) {
    const r = opt.rand || rng(opt.seed), kind = KINDS[tpl.kind];
    const need = tpl.pick || 3, maxTry = opt.maxTry || 50, pair = opt.pair || 'P01';
    const mine = myOk(tpl) ? (opt.custom || []).map(c => 'MY:' + c.code) : [];
    const allow = mine.concat(opt.rules ? (tpl.distractors || []).filter(id => opt.rules.includes(id)) : (tpl.distractors || []));
    if (effCount(tpl.kind, allow) < need) throw new Error(`模板 ${tpl.tpl}：可用的規則只有 ${effCount(tpl.kind, allow)} 條（互斥的算一條），至少要 ${need} 條`);
    const misMap = opt.misMap;
    const why = {}, note = m => why[m] = (why[m] || 0) + 1;
    for (let t = 0; t < maxTry; t++) {
      const fx = opt.fixed || [];                                          // 指定數字（重出某一題、測試用）
      const PA = sampleValid(tpl, r, fx[0]);
      const fxB = tpl.sameAB && PA ? Object.assign({}, fx[1] || {}, ...tpl.sameAB.map(k => ({ [k]: PA[k] }))) : fx[1];   // v3.15：sameAB 列的參數（題型方向，例如放回／不放回）A、B 卷相同，只換數字（老師 2026-11-11 裁定「方向固定、情境可換」）
      const PB = sampleValid(tpl, r, fxB);
      if (PA && !PB && tpl.sameAB) { note('B 卷照 A 卷的題型抽不到數字'); continue; }
      if (!PA || !PB) throw new Error(`模板 ${tpl.tpl}：抽不到符合 when（${tpl.when}）的數字`);
      const evA = evaluate(tpl, PA, allow, opt.custom), evB = evaluate(tpl, PB, allow, opt.custom);
      if (tpl.distinctAB) { const va = new Set(tpl.distinctAB.map(k => PA[k])); if (tpl.distinctAB.some(k => va.has(PB[k]))) { note('A、B 卷用到相同的數'); continue; } }
      if (JSON.stringify(PA) === JSON.stringify(PB) || (evA.ansKey === evB.ansKey && fill(tpl.stem, PA) === fill(tpl.stem, PB))) { note('A、B 卷數字相同'); continue; }
      let ruleOrder = opt.keepOrder ? allow : mine.concat(shuffle(allow.filter(x => !mine.includes(x)), r));   // 老師自己的迷思優先
      if (tpl.fallback && !opt.keepOrder) ruleOrder = ruleOrder.filter(x => !tpl.fallback.includes(x)).concat(ruleOrder.filter(x => tpl.fallback.includes(x)));   // v3.13：備用規則（例如兩個錯的版本）排在最後，前面的撞值或不適用才用
      const chosen = choose(evA, evB, tpl, ruleOrder, need, kind);
      if (!chosen) {   // 第 16 批第 3 步審核後：分開「勾選的迷思湊不到 need 個不同迷思的誘答」和「真的撞值」（只改失敗訊息，亂數消耗不變）
        const ok2 = new Set(ruleOrder.filter(id => evA.cands.some(d => d.rule === id) && evB.cands.some(d => d.rule === id)).map(id => exclOf(tpl.kind, id) || id));
        note(ok2.size < need ? `勾選的迷思在這一題只湊得到 ${ok2.size} 個不同迷思的誘答（每題要 ${need} 個）` : '誘答撞值（彼此相同或等於正解）'); continue; }
      const posA = Math.floor(r() * 4); let posB = Math.floor(r() * 3); if (posB >= posA) posB++;
      let A, B;   // v3.15：附圖畫不出來（例如 coordPlane 找不到放標籤的位置、ineqLine 端點貼著箭頭）時重抽數字
      try { A = buildItem(tpl, evA, chosen, 'A', pair, posA, r); B = buildItem(tpl, evB, chosen, 'B', pair, posB, r); } catch (e) { if (tpl.fig) { note('附圖：' + e.message); continue; } throw e; }
      // 產出的題目一律再驗算一次
      const bad = [A, B].map(it => ({ it, v: V.verifyItem(it, misMap) })).filter(x => x.v.status !== 'pass');
      if (bad.length) { note('驗算沒過：' + bad.map(x => x.it.id + ' ' + x.v.msgs.join('；')).join(' / ')); continue; }
      return [A, B];
    }
    const short = Object.keys(why).some(k => k.startsWith('勾選的迷思'));
    throw new Error(`模板 ${tpl.tpl} 試了 ${maxTry} 次都抽不到可用的數字（${Object.entries(why).map(([k, v]) => `${k} ${v} 次`).join('；')}）` + (short && tpl.pickNote ? `。${tpl.pickNote}` : ''));
  }

  // ---------- 出題器：多個模板 → fa-bank/1 ----------
  // spec：{ unit:{grade,code,name}, tpls:[模板], mis:[迷思表], count:組數, seed, rules:[老師勾的規則 id 或迷思代碼], title, id }
  function genBank(spec) {
    const r = rng(spec.seed), tpls = spec.tpls || [];
    if (!tpls.length) throw new Error('沒有模板');
    const custom = spec.custom || [];
    const misAll = (spec.mis || []).concat(GENERIC.filter(g => !(spec.mis || []).some(m => m.code === g.code)),
      custom.map(c => ({ code: c.code, name: c.name, desc: c.desc || '', example: `${c.expr}＝${c.wrong}`, remedy: c.fix || '', source: '老師自訂（我的迷思）：' + (c.desc || c.name), transforms: c.transforms })));
    const misMap = {}; misAll.forEach(m => misMap[m.code] = m);
    // 老師勾的可以是迷思代碼（PF09）或規則 id（PF09a）
    const allowRule = (tpl, id) => !spec.rules || spec.rules.includes(id) || spec.rules.includes(R[tpl.kind][id].mis);
    const usable = tpls.filter(tp => effCount(tp.kind, (tp.distractors || []).filter(id => allowRule(tp, id))) + (myOk(tp) ? custom.length : 0) >= (tp.pick || 3));
    if (!usable.length) throw new Error('勾選的迷思太少：每種模板至少要 3 條可用的規則');
    const count = spec.count || usable.length, items = [];
    // v3.26（第 16 批第 2 步審核後）：單一模板出不了題（例：勾的迷思在這個模板湊不到 3 個誘答）就略過它、用其他模板補足組數，
    //   略過的模板與原因放在 bank.skipped（給畫面顯示）；全部模板都失敗才丟錯。沒有失敗時輪替與亂數消耗順序和以前完全相同
    let alive = usable.slice(); const skipped = [];
    for (let i = 0; i < count; i++) {
      for (;;) {
        if (!alive.length) throw new Error('每一種模板都出不了題：' + skipped.map(x => `${x.tpl}（${x.reason}）`).join('；'));
        const tp = alive[i % alive.length];
        const rules = (tp.distractors || []).filter(id => allowRule(tp, id));
        let pr; try { pr = genPair(tp, { pair: 'P' + String(i + 1).padStart(2, '0'), rand: r, rules, misMap, custom }); }
        catch (e) { skipped.push({ tpl: tp.tpl, title: tp.title || '', reason: e.message }); alive = alive.filter(x => x !== tp); continue; }
        items.push(...pr); break;
      }
    }
    const used = new Set(items.flatMap(it => it.options.map(o => o.mis).filter(Boolean)));
    const u = spec.unit || {};
    const bank = {
      schema: 'fa-bank/1', id: spec.id || `T-${u.grade || ''}${u.code || ''}-${Date.now().toString(36)}`,
      title: spec.title || `${u.grade || ''} ${u.code || ''} ${u.name || ''}（模板出題）`.trim(), route: spec.route || 'B',
      unit: u, source: spec.source || '模板出題（不用 AI）：正解與誘答都由程式依錯誤規則算出，經自動驗算',
      createdAt: spec.date || new Date().toISOString().slice(0, 10),
      misconceptions: misAll.filter(m => used.has(m.code)),
      items, note: '每組平行題 A 卷第一場、B 卷第二場；同一組用同一組錯誤規則，只換數字'
    };
    if (skipped.length) bank.skipped = skipped;
    // 第 16 批第 3 步審核後：模板寫了 combos（每題可以出的誘答迷思組合）時，老師勾了、但在這組勾選下不可能出現的迷思（例：PV-judge 勾 PV01＋PV05＋PV08＋PV09＋PV17，
    //   PV17 只能和 PV06＋PV02 或 PV02＋PV14 一起出，一題都不會有）列在 bank.notUsed，附模板說明（pickNote）；沒有這種迷思就不加欄位（沒寫 combos 的模板不受影響）
    if (spec.rules) { const selC = new Set(spec.rules.map(id => { const tp = usable.find(t => (t.distractors || []).includes(id)); return tp ? R[tp.kind][id].mis : id; }));
      const notUsed = [...selC].filter(c => { const tps = usable.filter(tp => (tp.distractors || []).some(id => R[tp.kind][id].mis === c)); return tps.length && tps.every(tp => tp.combos && !tp.combos.some(cb => cb.includes(c) && cb.every(x => selC.has(x)))); });
      if (notUsed.length) bank.notUsed = notUsed.map(c => ({ code: c, reason: usable.filter(tp => (tp.distractors || []).some(id => R[tp.kind][id].mis === c)).map(tp => `${tp.title || tp.tpl}：${tp.pickNote || ''}`).join('；') })); }
    const vr = V.verifyBank(bank);
    if (vr.summary.fail !== 0 || vr.summary.pairOk !== vr.summary.pairs) throw new Error('模板題庫驗算沒過：' + JSON.stringify(vr.summary));
    bank.verify = vr.summary;
    return bank;
  }

  // 刪掉某個誘答、由規則補下一個（審題畫面用）：保留同一組數字，換掉這條規則
  function replaceDistractor(item, pairItem, tpl, ruleId, opt = {}) {
    const kind = KINDS[tpl.kind], used = item.options.filter(o => o.rule).map(o => o.rule);
    const keptEx = new Set(used.filter(id => id !== ruleId).map(id => exclOf(tpl.kind, id)).filter(Boolean));   // 留下的規則佔用的互斥組
    const pool = (tpl.distractors || []).filter(id => !used.includes(id) && !keptEx.has(exclOf(tpl.kind, id)) && (!opt.rules || opt.rules.includes(id) || opt.rules.includes(R[tpl.kind][id].mis)));
    for (const id of pool) {
      const a = runRule(tpl.kind, id, item.params), b = pairItem ? runRule(tpl.kind, id, pairItem.params) : a;
      if (!a || !b) continue;
      const clash = (it, d) => it.options.some(o => o.rule !== ruleId && kind.key(o.code !== undefined ? o.code : o.text) === kind.key(d.text));
      if (clash(item, a) || (pairItem && clash(pairItem, b))) continue;
      [[item, a], [pairItem, b]].forEach(([it, d]) => {
        if (!it) return; const o = it.options.find(x => x.rule === ruleId);
        Object.assign(o, { text: d.text, mis: d.mis, rule: id, trace: d.trace, fix: d.fix, feedback: `${d.trace}。${d.fix}。` }); delete o.teacherOk;
        if (tpl.optLabels) { delete o.code; optRelabel(it, tpl); }   // 第 12 批：選項是圖，附圖跟著換
      });
      return id;
    }
    return null;
  }

  // 換一組數字（審題畫面用）：同一模板、同一組規則、同一個題組代號，A、B 卷一起重抽；新數字要和原來不同
  function regenPair(tpl, A, B, opt = {}) {
    const used = A.options.filter(o => o.rule).map(o => o.rule);
    const custom = (opt.custom || []).filter(c => used.includes('MY:' + c.code));
    const builtin = used.filter(id => !id.startsWith('MY:'));
    const t2 = Object.assign({}, tpl, { pick: used.length });
    const old = JSON.stringify([A.params, B.params]);
    for (let k = 0; k < 10; k++) {
      const pair = genPair(t2, { pair: A.pair, rules: builtin, custom, misMap: opt.misMap, keepOrder: true, seed: opt.seed ? opt.seed + k : undefined });
      if (JSON.stringify([pair[0].params, pair[1].params]) !== old) return pair;
    }
    throw new Error('同一組規則抽不到不一樣的數字');
  }

  // 列出某些模板可用的迷思（只列有規則的）
  function rulesOf(tpls) {
    const m = {}; tpls.forEach(tp => (tp.distractors || []).forEach(id => { const rr = R[tp.kind][id]; (m[rr.mis] = m[rr.mis] || []).push({ tpl: tp.tpl, rule: id, name: rr.name }); }));
    return m;
  }


  // ============================================================
  // 動態附圖（v3.9）：模板寫 fig＝{ kind, …參數 }，參數字串可用 {算式}；產生的 SVG 一律能通過 verify.js 的 safeSVG（測試檢查 safeSVG(fig)＝fig）
  // kind：shapes（通用圖形清單）、numberLine（數線）、triangle（依三邊長畫三角形）、bars（長條圖）；之後各批依需要再加
  // ============================================================
  const f1 = v => (Math.round(v * 10) / 10).toFixed(1);
  const xesc = t => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const SV = {
    line: (x1, y1, x2, y2, o = {}) => `<line x1="${f1(x1)}" y1="${f1(y1)}" x2="${f1(x2)}" y2="${f1(y2)}" stroke="${o.c || '#333'}" stroke-width="${o.w || 1.8}"${o.dash ? ' stroke-dasharray="5 4"' : ''}/>`,
    text: (x, y, t, o = {}) => `<text x="${f1(x)}" y="${f1(y)}" font-size="${o.fs || 14}" text-anchor="${o.a || 'middle'}" fill="${o.c || '#333'}">${xesc(t)}</text>`,
    poly: (pts, o = {}) => `<polygon points="${pts.map(p => f1(p[0]) + ',' + f1(p[1])).join(' ')}" fill="${o.fill || 'none'}" stroke="${o.c || '#333'}" stroke-width="${o.w || 1.8}"${o.dash ? ' stroke-dasharray="5 4"' : ''}/>`,
    circle: (cx, cy, r, o = {}) => `<circle cx="${f1(cx)}" cy="${f1(cy)}" r="${f1(r)}" fill="${o.fill || 'none'}" stroke="${o.c || '#333'}" stroke-width="${o.w || 1.8}"/>`,
    rect: (x, y, w, h, o = {}) => `<rect x="${f1(x)}" y="${f1(y)}" width="${f1(w)}" height="${f1(h)}" fill="${o.fill || 'none'}" stroke="${o.c || '#333'}" stroke-width="${o.w || 1.8}"/>`,
    path: (d, o = {}) => `<path d="${d}" fill="${o.fill || 'none'}" stroke="${o.c || '#333'}" stroke-width="${o.w || 1.8}"${o.dash ? ' stroke-dasharray="5 4"' : ''}/>`
  };
