    EQ11: { mis: 'EQ11', name: '去括號漏乘第二項', fn: ({ a, b, c, d, s }) => ({ text: frT(c + s * b - d, a), trace: `−${a}${inn(s, b)} 寫成 −${a}x${pm(s, b)}，${b} 沒乘 ${a}：${c}−${a}x${pm(s, b)}＝${sgn(d)}，x＝${frT(c + s * b - d, a)}`, fix: `−${a} 要乘到每一項：−${a}${inn(s, b)}＝−${a}x${pm(s, a * b)}` }) },
