    WP06a: { mis: 'WP06', name: '盈餘與不足正負寫反', fn: ({ a, b, p, q }) => ({ text: `${a}x−${p}＝${b}x＋${q}`, trace: `「多 ${p}」寫成減、「少 ${q}」寫成加`, fix: `多出來的要加回去才是總數：${a}x＋${p}；不夠的要減掉：${b}x−${q}` }) },
    WP06b: { mis: 'WP06', name: '不足也寫成加', fn: ({ a, b, p, q, U }) => ({ text: `${a}x＋${p}＝${b}x＋${q}`, trace: `「少 ${q}」也寫成加 ${q}`, fix: `每人 ${b} ${U}還少 ${q} ${U}，總數比 ${b}x 少：${b}x−${q}` }) },
