  const repCx = (hi, c) => hi ? c % 3 : 3 + c % 2;
  F.registerFn('st7RepCx', (hi, c) => repCx(hi, c));
  // 極端值以外的 7 個數都比平均數小（hi＝1）或都比平均數大（hi＝0）（2026-11-12 審核：原本要求平均數超出一般值的範圍，hi＝0 幾乎出不來）
  F.registerFn('st7RepSide', (hi, p, MN, ...d) => d.every((x, i) => i === p - 1 || (hi ? x < MN : x > MN)));
  // 正解（中位數）是唯一小數：ST06（平均數）、ST04（原順序第 4、5 個的平均）都是整數就不出（ST08 一定是整數）
  F.registerFn('st7RepUD', (...d) => { const s = srt(d), m = (s[3] + s[4]) / 2; return !Number.isInteger(m) && Number.isInteger(sum(d) / 8) && Number.isInteger((d[3] + d[4]) / 2); });
  F.registerFn('st7RepW', x => REPC[x].w); F.registerFn('st7RepU', x => REPC[x].u); F.registerFn('st7RepWho', x => REPC[x].who); F.registerFn('st7RepGrp', x => REPC[x].grp);
  F.registerFn('st7RepLo', x => REPC[x].lo); F.registerFn('st7RepHi', x => REPC[x].hi); F.registerFn('st7RepElo', x => REPC[x].elo); F.registerFn('st7RepEhi', x => REPC[x].ehi);
  const rpD = P => { const a = [P.d1, P.d2, P.d3, P.d4, P.d5, P.d6, P.d7, P.d8], s = srt(a), cx = REPC[P.x]; return { a, s, m: (s[3] + s[4]) / 2, mean: sum(a) / 8, u: cx.u, cx, e: P.e }; };
  add('st7Rep', K.unitNum, {
    ST06: { mis: 'ST06', name: '以為平均數一定能代表大多數', fn: P => { const d = rpD(P), others = d.a.length - 1;
      return { value: d.mean, text: `${n2(d.mean)} ${d.u}`, trace: `以為平均數一定能代表${d.cx.grp}，選了平均數 ${n2(d.mean)} ${d.u}`,
        fix: `8 個數中有 ${others} 個${P.hi ? '不到' : '超過'} ${n2(d.mean)}，是 ${d.e} 這個極端值把平均數${P.hi ? '拉高' : '拉低'}；有極端值時用中位數較合適：排序後中間兩數 ${d.s[3]}、${d.s[4]} 的平均是 ${n2(d.m)}` }; } },
    ST04: { mis: 'ST04', name: '沒有先排序就取中間', fn: P => { const d = rpD(P), v = (d.a[3] + d.a[4]) / 2;
      return { value: v, text: `${n2(v)} ${d.u}`, trace: `沒有先排序，直接取原本順序第 4、5 個數 ${d.a[3]}、${d.a[4]}：(${d.a[3]}＋${d.a[4]})÷2＝${n2(v)}`, fix: `要先由小排到大：${J(d.s)}，中間兩數 ${d.s[3]}、${d.s[4]} 的平均才是中位數 ${n2(d.m)}` }; } },
    ST08: { mis: 'ST08', name: '偶數筆只取第 4 個數', fn: P => { const d = rpD(P);
      return { value: d.s[3], text: `${d.s[3]} ${d.u}`, trace: `排序成 ${J(d.s)} 後，只取第 4 個數 ${d.s[3]} 當中位數`, fix: `8 個數的正中間有兩個數（第 4、第 5 個），要取 ${d.s[3]} 和 ${d.s[4]} 的平均：(${d.s[3]}＋${d.s[4]})÷2＝${n2(d.m)}` }; } },
    ST08r: { mis: 'ST08', name: '偶數筆只取第 5 個數', fn: P => { const d = rpD(P);
      return { value: d.s[4], text: `${d.s[4]} ${d.u}`, trace: `排序成 ${J(d.s)} 後，只取第 5 個數 ${d.s[4]} 當中位數`, fix: `8 個數的正中間有兩個數（第 4、第 5 個），要取 ${d.s[3]} 和 ${d.s[4]} 的平均：(${d.s[3]}＋${d.s[4]})÷2＝${n2(d.m)}` }; } }
  });

  // ======================================================================
  // ST-mode：長條圖，選最合適的代表值（答案是眾數；題庫 P06 改成「選代表值」才有 3 個代碼）
  // ======================================================================
  const MODC = [
    { w: '鞋號', u: '號', why: '鞋店要依這班的資料決定哪一個鞋號進最多貨', L: [22, 23], st: 1, lab: v => `${v}號` },
    { w: '制服尺寸', u: '號', why: '學校要依這班的資料決定哪一個尺寸的制服訂最多件', L: [150, 155], st: 5, lab: v => `${v}號` }];
  F.registerFn('st7ModW', c => MODC[c].w); F.registerFn('st7ModWhy', c => MODC[c].why);
  F.registerFn('st7ModV', (c, l, i) => MODC[c].L[l] + i * MODC[c].st);
  F.registerFn('st7ModLabs', (c, l) => [0, 1, 2, 3].map(i => MODC[c].lab(MODC[c].L[l] + i * MODC[c].st)));
  F.registerFn('st7FMed', (c, l, f1, f2, f3, f4) => fmed([0, 1, 2, 3].map(i => MODC[c].L[l] + i * MODC[c].st), [f1, f2, f3, f4]));
  F.registerFn('st7ArgMaxU', (...f) => argmaxU(f));
  F.registerFn('st7IsInt', x => Number.isInteger(+(+x).toFixed(10)));
  // 長條圖展開成原始資料（給 check 的 fn:'mode' 重算眾數；v3.16 fillDeep 整串 {算式} 回傳陣列）
  F.registerFn('st7Expand', (c, l, f1, f2, f3, f4) => [f1, f2, f3, f4].flatMap((n, i) => Array(n).fill(MODC[c].L[l] + i * MODC[c].st)));
  const moD = P => { const cx = MODC[P.c], v = [0, 1, 2, 3].map(i => cx.L[P.l] + i * cx.st), f = [P.f1, P.f2, P.f3, P.f4], N = sum(f), im = argmaxU(f);
    return { cx, v, f, N, im, mode: v[im], mean: sum(v.map((x, i) => x * f[i])) / N, md: fmed(v, f), u: cx.u }; };
  add('st7Mode', K.unitNum, {
    ST06: { mis: 'ST06', name: '以為平均數一定最能代表', fn: P => { const d = moD(P);
      return { value: d.mean, text: `${n2(d.mean)} ${d.u}`, trace: `以為平均數最能代表全班，算了平均數 (${prodT(d.v, d.f)})÷${d.N}＝${n2(d.mean)}`,
        fix: `要知道哪一個${d.cx.w}最多人需要，要看出現最多次的資料，也就是眾數：${d.mode} ${d.u}有 ${d.f[d.im]} 人，最多` }; } },
    ST14: { mis: 'ST14', name: '把中位數當成眾數', fn: P => { const d = moD(P), N = d.N;
      return { value: d.md, text: `${n2(d.md)} ${d.u}`, trace: `用了中位數：${N} 人排序後${N % 2 ? `第 ${(N + 1) / 2} 人的${d.cx.w}是` : kth(d.v, d.f, N / 2) === kth(d.v, d.f, N / 2 + 1) ? `第 ${N / 2}、${N / 2 + 1} 人的${d.cx.w}都是` : `第 ${N / 2}、${N / 2 + 1} 人${d.cx.w}的平均是`} ${n2(d.md)} ${d.u}`,
        fix: `中位數是正中間的數，不一定是最多人的；最多人的是眾數：${d.mode} ${d.u}有 ${d.f[d.im]} 人` }; } },
    ST05: { mis: 'ST05', name: '眾數答成次數', fn: P => { const d = moD(P);
      return { value: d.f[d.im], text: `${d.f[d.im]} ${d.u}`, trace: `${d.mode} ${d.u}有 ${d.f[d.im]} 人最多，就把人數 ${d.f[d.im]} 當成答案`, fix: `眾數是出現最多次的那個資料（${d.cx.w}本身），不是出現幾次：答 ${d.mode} ${d.u}` }; } },
    ST05m: { mis: 'ST05', name: '眾數答成最大的數', fn: P => { const d = moD(P), mx = d.v[3];
      return { value: mx, text: `${mx} ${d.u}`, trace: `選了最大的${d.cx.w} ${mx} ${d.u}`, fix: `眾數是出現最多次的資料，不是最大的數：${d.mode} ${d.u}有 ${d.f[d.im]} 人，最多` }; } }
  });

  // ======================================================================
  // ST-wmean：（未分組）次數分配表求平均數（題庫 P07）
  // ======================================================================
  const WMC = [{ w: '上週借書本數', h: '借書本數（本）', u: '本' }, { w: '上週吃外食早餐天數', h: '外食天數（天）', u: '天' }, { w: '上個月看電影部數', h: '電影部數（部）', u: '部' }];
  F.registerFn('st7WmUD', (v1, v2, v3, v4, f1, f2, f3, f4) => { const v = [v1, v2, v3, v4], f = [f1, f2, f3, f4], N = sum(f), mn = sum(v.map((x, i) => x * f[i])) / N; return !Number.isInteger(mn) && Number.isInteger(sum(v) / 4) && Number.isInteger(fmed(v, f)); });
  F.registerFn('st7WmW', c => WMC[c].w); F.registerFn('st7WmU', c => WMC[c].u);
  F.registerFn('st7WmRows', (c, v1, v2, v3, v4, f1, f2, f3, f4) => [[WMC[c].h, '人數（人）'], [v1, f1], [v2, f2], [v3, f3], [v4, f4]]);
  F.registerFn('st7WmExpr', (v1, v2, v3, v4, f1, f2, f3, f4) => `(${v1}×${f1}+${v2}×${f2}+${v3}×${f3}+${v4}×${f4})÷${f1 + f2 + f3 + f4}`);
  F.registerFn('st7WmOk', (v1, v2, v3, v4, f1, f2, f3, f4) => { const v = [v1, v2, v3, v4], f = [f1, f2, f3, f4], S = sum(v.map((x, i) => x * f[i])), N = sum(f); return `總和 ${prodT(v, f)}＝${S}，${S}÷${N}＝${n2(S / N)}`; });
  const wmD = P => { const v = [P.v1, P.v2, P.v3, P.v4], f = [P.f1, P.f2, P.f3, P.f4], N = sum(f), S = sum(v.map((x, i) => x * f[i])); return { v, f, N, S, mean: S / N, u: WMC[P.c].u, im: argmaxU(f), md: fmed(v, f) }; };
  add('st7WMean', K.unitNum, {
    ST11: { mis: 'ST11', name: '沒乘人數，直接相加÷4', fn: P => { const d = wmD(P), x = sum(d.v) / 4;
      return { value: x, text: `${n2(x)} ${d.u}`, trace: `把 ${J(d.v)} 直接相加÷4：(${plusT(d.v)})÷4＝${n2(x)}，沒有乘人數`, fix: `每個值要乘人數再加總，除以總人數：(${prodT(d.v, d.f)})÷${d.N}＝${n2(d.mean)}` }; } },
    ST14: { mis: 'ST14', name: '把中位數當成平均數', fn: P => { const d = wmD(P), N = d.N;
      return { value: d.md, text: `${n2(d.md)} ${d.u}`, trace: `用了中位數：${N} 人排序後${N % 2 ? `第 ${(N + 1) / 2} 個` : `第 ${N / 2}、${N / 2 + 1} 個的平均`}是 ${n2(d.md)}`, fix: `平均數不一定在正中間，要算總和÷人數：(${prodT(d.v, d.f)})÷${d.N}＝${n2(d.mean)}` }; } },
    ST07: { mis: 'ST07', name: '以為平均數落在人數最多的值', fn: P => { const d = wmD(P); if (d.im < 0) return null; const x = d.v[d.im];
      return { value: x, text: `${x} ${d.u}`, trace: `${x} ${d.u}的人數最多（${d.f[d.im]} 人），就以為平均數是 ${x}`, fix: `平均數不一定落在人數最多的地方，要算總和÷人數：(${prodT(d.v, d.f)})÷${d.N}＝${n2(d.mean)}` }; } }
  });

  // ======================================================================
  // ST-gmean（表）／ST-pmean（直方圖＋折線圖）：分組資料用組中點估計平均數（題庫 P02）；k＝組數（sameAB）
  // ======================================================================
  const GMC = [{ w: '數學成績', u: '分', h: '成績（分）', wd: 10, L: [40, 50, 60] }, { w: '每天運動時間', u: '分鐘', h: '運動時間（分鐘）', wd: 10, L: [0, 10, 20] }, { w: '身高', u: '公分', h: '身高（公分）', wd: 5, L: [145, 150, 155] }];
  F.registerFn('st7GmW', c => GMC[c].w); F.registerFn('st7GmU', c => GMC[c].u); F.registerFn('st7GmL', (c, l) => GMC[c].L[l]); F.registerFn('st7GmWd', c => GMC[c].wd);
  const gmD = P => { const cx = GMC[P.c], L = cx.L[P.l], w = cx.wd, f = [P.f1, P.f2, P.f3, P.f4].slice(0, P.k), B = [...Array(P.k + 1)].map((_, i) => L + i * w), m = f.map((_, i) => L + i * w + w / 2), N = sum(f), S = sum(m.map((x, i) => x * f[i]));
    return { cx, L, w, f, B, m, N, S, mean: S / N, u: cx.u, im: argmaxU(f), lab: i => `${B[i]}～${B[i + 1]}` }; };
  F.registerFn('st7GmRows', (c, l, k, f1, f2, f3, f4) => { const d = gmD({ c, l, k, f1, f2, f3, f4 }); return [[d.cx.h, '人數（人）'], ...d.f.map((x, i) => [d.lab(i), x])]; });
  F.registerFn('st7GmBnd', (c, l, k) => { const L = GMC[c].L[l], w = GMC[c].wd; return [...Array(k + 1)].map((_, i) => L + i * w); });
  F.registerFn('st7GmFs', (k, f1, f2, f3, f4) => [f1, f2, f3, f4].slice(0, k));
  F.registerFn('st7GmExpr', (c, l, k, f1, f2, f3, f4) => { const d = gmD({ c, l, k, f1, f2, f3, f4 }); return `(${d.m.map((x, i) => `${n2(x)}×${d.f[i]}`).join('+')})÷${d.N}`; });
  F.registerFn('st7GmMean', (c, l, k, f1, f2, f3, f4) => gmD({ c, l, k, f1, f2, f3, f4 }).mean);
  F.registerFn('st7GmOk', (c, l, k, f1, f2, f3, f4) => { const d = gmD({ c, l, k, f1, f2, f3, f4 }); return `(${prodT(d.m, d.f)})÷${d.N}＝${n2(d.S)}÷${d.N}＝${n2(d.mean)}`; });
  // 中位數所在的組（N 偶數時第 N/2、N/2＋1 個要在同一組，否則 −1）
  const medGrp = f => { const N = sum(f), at = i => { let c = 0; for (let j = 0; j < f.length; j++) { c += f[j]; if (i <= c) return j; } return -1; };
    if (N % 2) return at((N + 1) / 2); const a = at(N / 2), b = at(N / 2 + 1); return a === b ? a : -1; };
  const gRules = (bndCode, bndName, isPoly) => ({
    [bndCode]: { mis: bndCode, name: bndName + '（下限）', fn: P => { const d = gmD(P), lo = d.B.slice(0, -1), x = sum(lo.map((b, i) => b * d.f[i])) / d.N;
      return { value: x, text: `${n2(x)} ${d.u}`, trace: isPoly ? `把折點畫在各組的下限（${d.lab(0)} 組的折點畫在 ${d.B[0]}），用 ${J(lo)} 代表各組：(${prodT(lo, d.f)})÷${d.N}＝${n2(x)}` : `用每組的下限 ${J(lo)} 代表各組：(${prodT(lo, d.f)})÷${d.N}＝${n2(x)}`,
        fix: `${isPoly ? '折點要畫在組中點' : '要用組中點代表各組'}，組中點是 ${J(d.m)}：(${prodT(d.m, d.f)})÷${d.N}＝${n2(d.mean)}` }; } },
    [bndCode + 'u']: { mis: bndCode, name: bndName + '（上限）', fn: P => { const d = gmD(P), hi = d.B.slice(1), x = sum(hi.map((b, i) => b * d.f[i])) / d.N;
      return { value: x, text: `${n2(x)} ${d.u}`, trace: isPoly ? `把折點畫在各組的上限（${d.lab(0)} 組的折點畫在 ${d.B[1]}），用 ${J(hi)} 代表各組：(${prodT(hi, d.f)})÷${d.N}＝${n2(x)}` : `用每組的上限 ${J(hi)} 代表各組：(${prodT(hi, d.f)})÷${d.N}＝${n2(x)}`,
        fix: `${isPoly ? '折點要畫在組中點' : '要用組中點代表各組'}，組中點是 ${J(d.m)}：(${prodT(d.m, d.f)})÷${d.N}＝${n2(d.mean)}` }; } },
    ST11: { mis: 'ST11', name: '組中點直接相加÷組數', fn: P => { const d = gmD(P), x = sum(d.m) / d.f.length; if (!fin(sum(d.m), d.f.length)) return null;
      return { value: x, text: `${n2(x)} ${d.u}`, trace: `把組中點 ${J(d.m)} 直接相加÷${d.f.length}：(${plusT(d.m)})÷${d.f.length}＝${n2(x)}，沒有乘人數`, fix: `每組的組中點要乘人數：(${prodT(d.m, d.f)})÷${d.N}＝${n2(d.mean)}` }; } },
    ST07: { mis: 'ST07', name: '以為平均數在人數最多的組', fn: P => { const d = gmD(P); if (d.im < 0) return null; const x = d.m[d.im];
      return { value: x, text: `${n2(x)} ${d.u}`, trace: `${d.lab(d.im)} ${d.u}這組人數最多，就說平均數是這組的組中點 ${n2(x)}`, fix: `平均數不一定在人數最多的組，要用組中點×人數加總再除以總人數：(${prodT(d.m, d.f)})÷${d.N}＝${n2(d.mean)}` }; } },
    ST14: { mis: 'ST14', name: '以為平均數在正中間那一組', fn: P => { const d = gmD(P), g = medGrp(d.f); if (g < 0) return null; const x = d.m[g], N = d.N;
      return { value: x, text: `${n2(x)} ${d.u}`, trace: `以為平均數就是落在正中間的數：${N} 人排在正中間的${N % 2 ? `第 ${(N + 1) / 2} 人` : `第 ${N / 2}、${N / 2 + 1} 人`}在 ${d.lab(g)} ${d.u}這組，就說平均數是組中點 ${n2(x)}`, fix: `正中間那一組是中位數所在的組，不是平均數；平均數要算 (${prodT(d.m, d.f)})÷${d.N}＝${n2(d.mean)}` }; } }
  });
  add('st7GMean', K.unitNum, gRules('ST15', '用組界代表該組', false));
  add('st7PMean', K.unitNum, gRules('ST02', '折點畫在組界上', true));

  // ======================================================================
  // ST-pie：人數 → 圓心角（題庫 P08，無附圖）
  // ======================================================================
  const PIEC = [{ t: '最喜歡的球類', x: '喜歡籃球' }, { t: '上學的方式', x: '搭公車' }, { t: '血型', x: 'O 型' }, { t: '早餐吃什麼', x: '吃三明治' }, { t: '參加的社團', x: '參加球類社團' }];
  F.registerFn('st7PieT', c => PIEC[c].t); F.registerFn('st7PieX', c => PIEC[c].x);
  const deg = x => `${n2(x)}°`;
  const sp = t => /^[0-9A-Za-z]/.test(t) ? ' ' + t : t;   // 中文後面接數字、英文字母時補空格
  const pieR = (get) => ({
    ST10: { mis: 'ST10', name: '人數直接當圓心角', fn: P => { const { a, N, x } = get(P);
      return { value: a, text: deg(a), trace: `把${sp(x)}的人數 ${a} 直接當成 ${a}°`, fix: `要先算${sp(x)}占全班的比例 ${a}÷${N}，再乘 360°：${a}÷${N}×360°＝${deg(a * 360 / N)}` }; } },
    ST13: { mis: 'ST13', name: '百分率直接當圓心角', fn: P => { const { a, N, x } = get(P); if (!fin(a * 100, N, 1)) return null; const p = a * 100 / N;
      return { value: p, text: deg(p), trace: `算出${sp(x)}占 ${a}÷${N}＝${n2(p)}%，就把 ${n2(p)} 當成圓心角 ${n2(p)}°`, fix: `${n2(p)}% 還要乘 360°：${n2(p)}%×360°＝${deg(a * 360 / N)}` }; } },
    ST12: { mis: 'ST12', name: '比例用部分÷其餘', fn: P => { const { a, N, x } = get(P); if (2 * a >= N || !fin(a * 360, N - a, 1)) return null; const v = a * 360 / (N - a);
      return { value: v, text: deg(v), trace: `用 ${a}÷${N - a}（${x}的人÷其他人）當比例：${a}÷${N - a}×360°＝${deg(v)}`, fix: `比例要除以全部的 ${N} 人：${a}÷${N}×360°＝${deg(a * 360 / N)}` }; } }
  });
