  // ---------- 反向相似（公用角）：w＝0：∠ADE＝∠C，AD＝s1、AE＝s2、AC＝L，求 AB；w＝1：∠AED＝∠B，AE＝s1、AD＝s2、AB＝L，求 AC ----------
  const anti = w => w ? { P: 'AE', Q: 'AD', Lg: 'AB', X: 'AC', eq: '∠AED＝∠B', cor: 'E 對應 B，應是 △AED～△ABC', ok: 'AE：AB＝AD：AC', wrongT: '△ADE～△ABC', wrongEq: 'AD：AB＝AE：AC', small: '△AED', big: '△ABC' }
    : { P: 'AD', Q: 'AE', Lg: 'AC', X: 'AB', eq: '∠ADE＝∠C', cor: 'D 對應 C，應是 △ADE～△ACB', ok: 'AD：AC＝AE：AB', wrongT: '△ADE～△ABC', wrongEq: 'AD：AB＝AE：AC', small: '△ADE', big: '△ACB' };
