    CL08: { mis: 'CL08', name: 'd 與 r 的關係弄反', fn: P => { const { o, D } = P, r = D / 2, i = i8(P); if (i === undefined) return null; const d = ds(P)[i], k = cmp(d, r);
      return { text: STM(o, i, -k), trace: `把 d 和 r 的關係弄反：${OBJ(o, i)} 到圓心 ${d}，比半徑 ${r} ${k > 0 ? '大' : '小'}，以為${k > 0 ? (o ? '點在圓裡面' : '直線會穿過圓，交於兩點') : (o ? '點在圓外面' : '直線離圓很遠，不相交')}`, fix: `d 愈大離圓心愈遠：${d}${CMPT(d, r)}${r}，${STM(o, i, k)}` }; } },
    CL13: { mis: 'CL13', name: '以為要看圖才能判斷', fn: ({ o, o13, D }) => ({ text: `沒有圖，無法判斷${SP(OBJ(o, o13))}和圓 O 的位置關係`, trace: `沒有圖，就以為無法判斷${SP(OBJ(o, o13))}和圓 O 的位置關係`, fix: `只要比較圓心到${o ? '點' : '直線'}的距離 d 和半徑 r＝${D / 2}，不用看圖也能判斷` }) }
