  const sv = (sc, v) => { const S = PSC[sc], V = S && S.vs[v]; if (!V) return null; return Object.assign({ T: S.T, lines: S.lines }, V, { S }); };
  const rnOf = (S, L) => { const a = S.alts[L] || S.alts[0], m = {}; [...S.P].forEach((c, i) => m[c] = a[i]); return t => String(t).replace(/[A-Z]/g, c => m[c] || c); };
  const rsT = (rn, r) => r.startsWith('@') ? rn(r.slice(1)) : r;                      // 理由：條件型括號換字母，固定用語不換
