  F.registerFn('pf9OkN', (sc, v, rk, g, k, o) => { const V = sv(sc, v); if (!V || g >= goalsOf(V, rk).length) return false; return p10Of(V, rk, g, k).length > 0; });
  const corrR = (V, rk) => '對應' + (rk ? '角' : '邊') + '相等';
  const congT = (V, rn) => `△${rn(V.T[0])}≅△${rn(V.T[1])}`;
  F.registerFn('pf9T', (sc, v, L, i) => { const V = sv(sc, v); return rnOf(V.S, L)(V.T[i]); });
  F.registerFn('pf9Giv', (sc, v, L) => { const V = sv(sc, v), rn = rnOf(V.S, L); return V.giv.map(rn).join('；'); });
  F.registerFn('pf9Mk', (sc, v, L) => { const V = sv(sc, v); return rnOf(V.S, L)(V.mk); });
