  const perm = (a, seed) => { a = a.slice(); let s = (seed * 2654435761 + 97) >>> 0; for (let i = a.length - 1; i > 0; i--) { s = (Math.imul(s, 1103515245) + 12345) >>> 0; const j = s % (i + 1); [a[i], a[j]] = [a[j], a[i]]; } return a; };
