  const jRight = (S, L, ov) => { const [l1, l2] = JLET[L], A = jSet(S.ty[0], l1, ov & 1), B = jSet(S.ty[1], l2, ov >> 1 & 1); return { A, B, l1, l2 }; };
  function jAnsT(S, L, ov, cs) { const R = jRight(S, L, ov), c = jChain(S, R.A, R.B, [R.l1, R.l2], cs === 0); return jProof(S, `a＝${R.A}、b＝${R.B}`, `${R.l1}、${R.l2}`, c); }
  const jRightFix = (S, P) => { const R = jRight(S, P.L, P.ov), c = jChain(S, R.A, R.B, [R.l1, R.l2], true); return `設 a＝${R.A}、b＝${R.B}（${R.l1}、${R.l2} 是整數），${S.E}＝${c.chain.join('＝')}，${c.Q} 是整數，所以 ${S.E} 一定是${PN9(S.p)}`; };
  // ---------- 成立的不等式：平方差證明（cs 偶數＝康軒 p.144 例8 寫法、奇數＝翰林 p.151 例8 寫法）----------
  const jIneqAns = (S, cs, y1) => { const [u, v] = S.vs, D = `${u}²−${v}²`, Pr = `(${u}＋${v})(${u}−${v})`;
    return cs % 2 === 0 ? `${D}＝${Pr}，因為 ${u}＞${v}＞0，所以 ${u}＋${v}＞0、${u}−${v}＞0，則 ${Pr}＞0，即 ${D}＞0，故 ${u}²＞${v}²，這句話一定成立`
      : `${y1 ? '' : '因為 '}${D}＝${Pr}，已知 ${u}＞${v}，所以 ${u}−${v} 為正數，又 ${u}＋${v} 為正數，故 ${D}＞0，即 ${u}²＞${v}²，這句話一定成立`; };
  const jIneqFix = S => { const [u, v] = S.vs; return `${u}²−${v}²＝(${u}＋${v})(${u}−${v})，${u}、${v} 是正數又 ${u}＞${v}，${u}＋${v}、${u}−${v} 都是正數，乘起來大於 0，所以 ${u}²＞${v}² 一定成立`; };
  F.registerFn('jg9Ans', (pp, L, ov, cs, x1, cl, y1) => { const S = jp(pp); return S.ineq ? jIneqAns(S, cs, y1) : S.tf ? jAnsT(S, L, ov, cs) : cl ? jCexL(S, jAnsX(pp, x1), cl) : jCex(S, jAnsX(pp, x1)); });
