  const ppHow = (S, rn) => { const [a, b] = ppAka(S, rn); return `要找全等後 ${rn(S.X)} 就是對應${ppKind(S)}的兩個三角形：先找分別含 ${a}、${b} 的 △${rn(S.ans[0])}、△${rn(S.ans[1])}，再數條件：${rn(S.aw)} 全等性質，△${rn(S.ans[0])}≅△${rn(S.ans[1])}`; };
