  // 附圖：H6 沿用 pfXY 的 S2（含交點 F）；S3 等腰△兩腰中點
  const ppXY = (S, sh) => { if (S.fig === 'H6') return pfXY({ S: { id: 'S2' }, f: { F: 1 } }, sh);
    const h = [1.3, 1.6, 1.9, 2.2, 1.45][sh], A = [0, h], B = [-1, 0], C = [1, 0], D = [-0.5, h / 2], E = [0.5, h / 2]; return { A, B, C, D, E, F: [0, h / 3] }; };
  const PP_SEG = { H6: ['AB', 'AC', 'BC', 'BD', 'CE', 'AF'], S3: ['AB', 'AC', 'BC', 'BE', 'CD'] };
