  const ppSegs = S => PP_SEG[S.fig].concat(S.de ? ['DE'] : [], S.af ? ['AF'] : []);
  F.registerFn('pp9Ln', (s, L) => ppRn(L)(PP_LN[ppQ(s).fig]));
