    // 等長記號畫在線段正中點（審核建議 2 試過改畫在 0.36、0.64 處避開垂足、交點，但那一段中間有垂足或交點時，記號會落在子線段上、看起來像標 BF、AE，
    //   意思更錯，所以維持中點；要避開重疊得改 _figs_geo 的記號畫法，請主程式判斷）
    const tk = {}; G.tk.forEach(([x, n]) => { tk[x] = n; tk[x[1] + x[0]] = n; });
    const segs = sg.map(x => [rn(x[0]), rn(x[1]), tk[x] ? { ticks: tk[x] } : {}]);
    G.tk.forEach(([x, n]) => { if (!sg.includes(x) && !sg.includes(x[1] + x[0])) segs.push([rn(x[0]), rn(x[1]), { draw: 0, ticks: n }]); });
    const rights = G.rt ? [['D', 'A', 'B'], ['E', 'A', 'C']].map(([at, p, q]) => ({ at: rn(at), p: rn(p), q: rn(q) })) : [];
    return { pts, segs, angles: [], rights };
