  F.registerFn('pp9Fig', (s, L, sh, part) => ppFig(s, L, sh)[part]);
  // ---------- 規則 ----------
  const PPZ = P => { const S = ppQ(P.s, P.xv), rn = ppRn(P.L); return { S, rn, X: rn(S.X), xs: ppXs(rn, S), how: ppHow(S, rn) }; };
  // 複核後：回饋裡的兩個三角形照選項顯示的前後順序寫（sw＝1 時對調）
  const tri2 = (rn, [a, b], sw) => sw ? `△${rn(b)}、△${rn(a)}` : `△${rn(a)}、△${rn(b)}`;
