    const tbox = (x, y, t, fs, an) => { const w = tw(t, fs), x0 = an === 'middle' ? x - w / 2 : an === 'end' ? x - w : x; return [x0 - 1, y - fs * 0.82, x0 + w + 1, y + fs * 0.22]; };
