    PO01: { mis: 'PO01', name: '只有兩種結果就各 1/2', fn: P => ({ text: '1/2', trace: `以為「取到${P.Ct}球」和「沒取到${P.Ct}球」兩種結果各 1/2`, fix: `兩種的球數不同，機會不相等：${P.N} 顆中只有 ${P.k} 顆${P.Ct}球，機率是 ${frT(P.k, P.N)}` }) },
    PO08: { mis: 'PO08', name: '用有利÷不利', fn: P => ({ text: frT(P.k, P.N - P.k), trace: `用${P.Ct}球數÷其他球數：${P.k}/${P.N - P.k}${eqR(P.k, P.N - P.k)}`, fix: `分母要用所有球的個數 ${P.N}：${P.k}/${P.N}${eqR(P.k, P.N)}` }) },
    PO07: { mis: 'PO07', name: '沒有約成最簡分數', fn: P => red(P.k, P.N) ? { text: frRaw(P.k, P.N), trace: `${P.Ct}球 ${P.k} 顆、全部 ${P.N} 顆都數對了，寫成 ${frRaw(P.k, P.N)} 沒有約成 ${frT(P.k, P.N)}`, fix: `再約分：${frRaw(P.k, P.N)}＝${frT(P.k, P.N)}` } : null }
