  const EV = [d => `出現 ${d} 點`, () => '點數是 3 的倍數', () => '點數大於 4', () => '點數小於 5', () => '點數小於 3'], EVN = [1, 2, 2, 4, 2];
  const evT = P => EV[P.ev || 0](P.d), evE = P => EVN[P.ev || 0], evD = P => evT(P) + (/\d$/.test(evT(P)) ? ' ' : '');   // evD：後面接「的」時，數字後補空格
