  const ang2 = (o, a, b, Hh) => { const z = PJ(P3(o, Hh)), x = PJ(P3(a, Hh)), w = PJ(P3(b, Hh)), u = [x[0] - z[0], x[1] - z[1]], v = [w[0] - z[0], w[1] - z[1]];
    return Math.acos(Math.max(-1, Math.min(1, (u[0] * v[0] + u[1] * v[1]) / Math.hypot(...u) / Math.hypot(...v)))) * 180 / Math.PI; };
