  const cnN = n => n <= 10 ? CN[n] : n < 20 ? '十' + CN[n - 10] : n === 20 ? '二十' : String(n);
  const POLY = { 3: '正三角形', 4: '正方形', 5: '正五邊形', 6: '正六邊形' };
