  const add = (kind, key, rules) => { Object.values(rules).forEach(r => { if (!r.excl) r.excl = r.mis; }); F.registerKind(kind, { key }, rules); };
  // 解的寫法：roots 是 [分子, 分母] 或整數；兩個解由小到大
  const val = r => Array.isArray(r) ? r[0] / r[1] : r, txt = r => Array.isArray(r) ? frT(r[0], r[1]) : sgn(r);
  const sol = (...rs) => { const u = rs.slice().sort((a, b) => val(a) - val(b)); return u.map(r => `x＝${txt(r)}`).join(' 或 '); };
  const dbl = r => `x＝${txt(r)}（重根）`;
  // 比對鍵：解的集合相同就算同一個（「x＝3/2」和「x＝3/2（重根）」也算同一個）
  const rootKey = t => { const s = String(t).replace(/\s+/g, ''); if (/無解|沒有/.test(s)) return 'R:none';
    const vs = (s.match(/＝(−?[\d/]+)/g) || []).map(m => m.slice(1)); if (!vs.length) return 'T:' + s;
    return 'R:' + [...new Set(vs.map(v => F.keys.num(v)))].sort().join('|'); };
  const Q2 = (A, B, C) => (A === 1 ? '' : sgn(A)) + 'x²' + (B ? (B > 0 ? '＋' : '−') + (Math.abs(B) === 1 ? '' : Math.abs(B)) + 'x' : '') + (C ? (C > 0 ? '＋' : '−') + Math.abs(C) : '');

  // 哪一個是一元二次方程式（check: isQuadEq）；這一題只有 QF07、QF08 兩種錯法，QF07 兩種寫法例外允許同題出現（待老師確認）
  add('qfDef', F.keys.text, {
    QF07a: { mis: 'QF07', excl: 'QF07a', name: '沒化簡就判斷（x² 消掉）', fn: ({ b, c }) => ({ text: `x²＋${b}x＝x²−${c}`, trace: `看到有 x² 就以為是一元二次方程式`, fix: `移項化簡後 x² 消掉了，剩 ${b}x＋${c}＝0，是一元一次方程式` }) },
    QF07b: { mis: 'QF07', excl: 'QF07b', name: '沒化簡就判斷（展開後 x² 消掉）', fn: ({ p, q, c }) => ({ text: `(x＋${p})(x−${q})＝x²＋${c}`, trace: `左邊乘開有 x²，就以為是一元二次方程式`, fix: `展開移項後 x² 消掉了：${polyT(p - q, -p * q - c)}＝0，是一元一次方程式` }) },
    QF08: { mis: 'QF08', name: '沒等號也當方程式', fn: ({ b, d }) => ({ text: Q2(1, -b, d), trace: `${Q2(1, -b, d)} 有 x²，就以為是一元二次方程式`, fix: `沒有等號，只是一個多項式，不是方程式` }) }
  });
  // x²−bx＝c（解是 −q、p）
  add('qfRight', rootKey, {
    QF09: { mis: 'QF09', name: '把右邊當成 0', fn: ({ p, q }) => ({ text: sol(0, p - q), trace: `把右邊的 ${p * q} 當成 0：x(x−${p - q})＝0，得 x＝0 或 x＝${p - q}`, fix: `要先移項讓右邊為 0：${Q2(1, -(p - q), -p * q)}＝0，(x＋${q})(x−${p})＝0` }) },
    QF10: { mis: 'QF10', name: '找到一個解就停', fn: ({ p, q }) => ({ text: sol(p), trace: `試出 x＝${p} 代入成立，就只寫一個解`, fix: `一元二次方程式可能有兩個解，要用因式分解找全部：x＝−${q} 也成立` }) },
    QF04: { mis: 'QF04', name: '一次因式解的正負號錯', fn: ({ p, q }) => ({ text: sol(q, -p), trace: `分解成 (x＋${q})(x−${p})＝0 對了，解的正負號卻寫反：x＝${q} 或 x＝−${p}`, fix: `x＋${q}＝0 的解是 x＝−${q}、x−${p}＝0 的解是 x＝${p}` }) }
  });
  // (x−p)(ax＋aq)＝0
  add('qfProd0', rootKey, {
    QF03: { mis: 'QF03', name: '「或」當成「且」', fn: ({ p, q }) => ({ text: '無解', trace: `以為 x 要同時是 ${p} 和 −${q}，不可能，所以無解`, fix: `A×B＝0 是 A＝0「或」B＝0，兩個都是解` }) },
    QF04: { mis: 'QF04', name: '一次因式解的正負號錯', fn: ({ a, p, q }) => ({ text: sol(-p, q), trace: `解的正負號寫反：x−${p}＝0 寫成 x＝−${p}、${a}x＋${a * q}＝0 寫成 x＝${q}`, fix: `x−${p}＝0 的解是 x＝${p}；兩個解是 ${p} 和 −${q}` }) },
    QF05: { mis: 'QF05', name: '一次因式忘了除係數', fn: ({ a, p, q }) => ({ text: sol(p, -a * q), trace: `${a}x＋${a * q}＝0 直接寫成 x＝−${a * q}，忘了除以 ${a}`, fix: `${a}x＝−${a * q}，x＝−${a * q}÷${a}＝−${q}` }) }
  });
  // ax²＝bx
  add('qfDiv', rootKey, {
    QF02: { mis: 'QF02', name: '同除含 x 的式子', fn: ({ a, b }) => ({ text: sol([b, a]), trace: `兩邊同除以 x，只得 x＝${frT(b, a)}`, fix: `x 可能是 0，不能除；移項提公因式：x(${polyT(a, -b)})＝0，x＝0 或 x＝${frT(b, a)}` }) },
    QF10: { mis: 'QF10', name: '找到一個解就停', fn: () => ({ text: sol(0), trace: `看出 x＝0 代入成立，就只寫一個解`, fix: `還有另一個解，要提公因式找全部` }) },
    QF04: { mis: 'QF04', name: '一次因式解的正負號錯', fn: ({ a, b }) => ({ text: sol(0, [-b, a]), trace: `x(${polyT(a, -b)})＝0 對了，${polyT(a, -b)}＝0 的解卻寫成負的`, fix: `${polyT(a, -b)}＝0，x＝${frT(b, a)}` }) }
  });
  // ax(x−p)＝b(x−p)
  add('qfCommon', rootKey, {
    QF02: { mis: 'QF02', name: '同除含 x 的式子', fn: ({ a, b, p }) => ({ text: sol([b, a]), trace: `兩邊同除以 (x−${p})，只剩 ${a}x＝${b}`, fix: `x−${p} 可能是 0，不能除；要移項提出整個 (x−${p})：(x−${p})(${polyT(a, -b)})＝0` }) },
    QF04: { mis: 'QF04', name: '一次因式解的正負號錯', fn: ({ a, b, p }) => ({ text: sol(-p, [b, a]), trace: `(x−${p})(${polyT(a, -b)})＝0 對了，x−${p}＝0 卻寫成 x＝−${p}`, fix: `x−${p}＝0 的解是 x＝${p}` }) },
    QF05: { mis: 'QF05', name: '一次因式忘了除係數', fn: ({ a, b, p }) => (a === 1 || b === p) ? null : ({ text: sol(p, b), trace: `${polyT(a, -b)}＝0 寫成 x＝${b}，忘了除以 ${a}`, fix: `${a}x＝${b}，x＝${frT(b, a)}` }) }
  });
