    QA06: { mis: 'QA06', name: '回答的不是所求的量', fn: ({ p0, x0, d }) => ({ value: p0, text: `${p0} 元`, trace: `解出 x 後沒有回到題目，答成原來的每人費用 ${p0} 元`, fix: `增加 ${x0} 人後每人少收 ${d}×${x0}＝${d * x0} 元` }) },
    QA11: { mis: 'QA11', name: '只寫增加量沒回到所求', fn: ({ x0, d }) => ({ value: d * x0, text: `${d * x0} 元`, trace: `解出 x＝${x0}，算出每人少收 ${d * x0} 元就作答`, fix: `${d * x0} 元是少收的錢，每人要付的是原價減掉它` }) }
