    DS05: { mis: 'DS05', name: '把以 B[a] 為下限的那組也減掉', fn: P => { const d = D(P), a = P.a, b = P.bb; if (a + 1 >= b) return null;
      return { value: d.C[b] - d.C[a + 1], text: ren(d.C[b] - d.C[a + 1]), trace: `把 ${d.lab(a + 1)} ${d.u}這組當成「未滿 ${d.B[a]} ${d.u}」，減掉了未滿 ${d.B[a + 1]} ${d.u}的 ${d.C[a + 1]} 人：${d.C[b]}−${d.C[a + 1]}＝${d.C[b] - d.C[a + 1]}`, fix: `${d.lab(a + 1)} ${d.u}的人都是 ${d.B[a]} ${d.u}以上（含），要留在區間裡；只減掉未滿 ${d.B[a]} ${d.u}的 ${d.C[a]} 人：${d.C[b]}−${d.C[a]}＝${d.C[b] - d.C[a]} 人` }; } },
    DS05u: { mis: 'DS05', name: '以為 B[a] 屬於以它為上限的那組', fn: P => { const d = D(P), a = P.a, b = P.bb; if (a < 2) return null;
      return { value: d.C[b] - d.C[a - 1], text: ren(d.C[b] - d.C[a - 1]), trace: `以為 ${d.B[a]} ${d.u}算在 ${d.lab(a)} ${d.u}那組，把這組也算進區間，只減掉未滿 ${d.B[a - 1]} ${d.u}的 ${d.C[a - 1]} 人：${d.C[b]}−${d.C[a - 1]}＝${d.C[b] - d.C[a - 1]}`, fix: `每一組含下限、不含上限，${d.B[a]} ${d.u}在 ${d.lab(a + 1)} ${d.u}這組；${d.lab(a)} ${d.u}的人都未滿 ${d.B[a]} ${d.u}，要減掉未滿 ${d.B[a]} ${d.u}的 ${d.C[a]} 人：${d.C[b]}−${d.C[a]}＝${d.C[b] - d.C[a]} 人` }; } },
