    DS03: { mis: 'DS03', name: '累積值當成該組的值', fn: P => { const g = RG(P), j = g.j; if (P.v) return null;
      return { value: cnt(g.N, g.p[j]), text: ren(cnt(g.N, g.p[j])), trace: `把未滿 ${g.B[j]} ${g.u}的 ${g.p[j]}% 當成這一組的相對次數，算成 ${g.N}×${g.p[j]}%＝${n2(cnt(g.N, g.p[j]))}`, fix: `這一組要用兩個累積值相減：${g.p[j]}%−${g.p[j - 1]}%＝0%，${g.N}×0%＝0 人` }; } },
    DS07: { mis: 'DS07', name: '區間只讀一端', fn: P => { const g = RG(P); if (!P.v || g.i0 === 0) return null;
      return { value: cnt(g.N, g.p[g.i1]), text: ren(cnt(g.N, g.p[g.i1])), trace: `只讀了未滿 ${g.B[g.i1]} ${g.u}的 ${g.p[g.i1]}%，算成 ${g.N}×${g.p[g.i1]}%＝${n2(cnt(g.N, g.p[g.i1]))}，沒有減掉未滿 ${g.B[g.i0]} ${g.u}的 ${g.p[g.i0]}%`, fix: `區間要用兩個累積值相減：${g.p[g.i1]}%−${g.p[g.i0]}%＝${g.Dl}%，${g.N}×${g.Dl}%＝${n2(cnt(g.N, g.Dl))} 人` }; } },
    DS13: { mis: 'DS13', name: '百分比當成人數', fn: P => { const g = RG(P); if (!P.v || g.Dl >= g.N) return null;
      return { value: g.Dl, text: ren(g.Dl), trace: `算出 ${g.p[g.i1]}%−${g.p[g.i0]}%＝${g.Dl}%，就說有 ${g.Dl} 人`, fix: `${g.Dl}% 是占全部的百分之幾，要再乘總人數：${g.N}×${g.Dl}%＝${n2(cnt(g.N, g.Dl))} 人` }; } }
