  F.registerFn('asW', (a, S) => { if (S % 2) return 0; for (let m = 1; m <= 200; m++) { const v = m * (a + m - 1); if (v === S / 2) return m; if (v > S) break; } return 0; });
  F.registerFn('asW6', (a, S) => { for (let m = 1; m <= 200; m++) { const v = m * (a + 2 * (m - 1)); if (v === 2 * S) return m; if (v > 2 * S) break; } return 0; });

