  const VN = [{ A: 'A', B: 'B', C: 'C', D: 'D', E: 'E' }, { A: 'P', B: 'Q', C: 'R', D: 'S', E: 'T' }, { A: 'A', B: 'B', C: 'C', D: 'D', E: 'F' }];
  F.registerFn('ia8V', (nm, k) => VN[nm][k]);
