    IA06b: { mis: 'IA06', name: '把底邊另一端的角當成相鄰內角', fn: ({ g1, g2, vx }) => { const { X, Y } = EXN(vx); return { ...deg(180 - g2), trace: `看到 ${Y} 也在直線 ${Y}D 上，就用 180°−${g2}°＝${180 - g2}°，把 ∠${Y} 當成和 ∠A${X}D 相鄰的內角`, fix: `和 ∠A${X}D 拼成一直線的是 ∠A${X}${Y}；∠A、∠${Y} 是內對角，∠A${X}D＝∠A＋∠${Y}＝${g1 + g2}°` }; } },
    IA09: { mis: 'IA09', name: '周角減內角當外角', fn: ({ g1, g2, vx }) => { const { X, Y } = EXN(vx), i = 180 - g1 - g2; return { ...deg(360 - i), trace: `先算出 ∠A${X}${Y}＝${i}°，再用 360°−${i}°＝${360 - i}° 當成 ${X} 點的外角，取的是周角剩下的部分`, fix: `外角是和內角拼成一直線的角：180°−${i}°＝${180 - i}°` }; } }
