  add('ia8Split', K.unitNum, {
    IA10: { mis: 'IA10', name: '內部分割多算周角', fn: ({ n, v }) => v !== 0 ? null : { ...deg(n * 180), trace: `用 ${n}×180°＝${n * 180}°，把 O 點周圍的角也算進去了`, fix: `O 點周圍的角合起來是 360°，不是內角，要扣掉：${n * 180}°−360°＝${(n - 2) * 180}°` } },
    IA15: { mis: 'IA15', name: '以為分成 n 個三角形', fn: ({ n, v }) => v !== 1 ? null : { ...deg(n * 180), trace: `以為${CN[n]}邊形分成 ${n} 個三角形：${n}×180°＝${n * 180}°`, fix: `從頂點 A 畫對角線，${CN[n]}邊形分成 ${n}−2＝${n - 2} 個三角形：(${n}−2)×180°＝${(n - 2) * 180}°` } },
    IA11: { mis: 'IA11', name: '對角線數當三角形數', fn: ({ n, v }) => ({ ...deg((n - 3) * 180), trace: v ? `把從頂點 A 畫出的 ${n - 3} 條對角線當成三角形個數：(${n}−3)×180°＝${(n - 3) * 180}°` : `用 (${n}−3)×180°＝${(n - 3) * 180}°，把從一個頂點畫出的對角線條數 ${n - 3} 當成三角形個數`, fix: `從一個頂點畫對角線，${CN[n]}邊形分成 ${n}−2＝${n - 2} 個三角形，內角和是 (${n}−2)×180°＝${(n - 2) * 180}°` }) },
    IA13: { mis: 'IA13', name: '三角形多數一個', fn: ({ n }) => ({ ...deg((n - 1) * 180), trace: `以為${CN[n]}邊形分成 ${n}−1＝${n - 1} 個三角形：(${n}−1)×180°＝${(n - 1) * 180}°`, fix: `四邊形一條對角線分成 2 個三角形，三角形總是比邊數少 2：(${n}−2)×180°＝${(n - 2) * 180}°` }) },
    IA07: { mis: 'IA07', name: '多邊形內角和寫成 360°', fn: ({ n }) => ({ ...deg(360), trace: `把${CN[n]}邊形的內角和寫成 360°（這是四邊形內角和、也是外角和的度數）`, fix: `${CN[n]}邊形要分割成三角形來算：(${n}−2)×180°＝${(n - 2) * 180}°` }) }
  });

