  F.registerFn('ia8MissT', (n, k, x, y) => { const L = LET.slice(0, n), a = L.slice(0, k).split('').map(c => `∠${c}`).join('＝') + `＝${x}°`, m = n - 1 - k; return m ? `${a}，${L.slice(k, n - 1).split('').map(c => `∠${c}`).join('＝')}＝${y}°` : a; });
