    SQ11: { mis: 'SQ11', name: '等長垂直張冠李戴', fn: ({ a, b }) => ({ value: 2 * a * a, trace: `以為菱形的兩條對角線等長，BD＝AC＝${2 * a}：${2 * a}×${2 * a}÷2＝${2 * a * a}`, fix: `對角線等長的是長方形；菱形的對角線是互相垂直平分，BD＝2×OB＝${2 * b}，面積＝${2 * a}×${2 * b}÷2＝${2 * a * b}` }) },
    SQ06: { mis: 'SQ06', name: '對角線相乘忘了除以2', fn: ({ a, b }) => ({ value: 4 * a * b, trace: `兩條對角線直接相乘 ${2 * a}×${2 * b}＝${4 * a * b}`, fix: `菱形只占以對角線為長、寬的長方形的一半，要再除以 2：${2 * a}×${2 * b}÷2＝${2 * a * b}` }) }
